import { API_BASE_URL } from '../config/api';

export type TrackingStatus = 'placed' | 'shipped' | 'out-for-delivery' | 'delivered';

export interface TrackingUpdate {
  orderId: string;
  status: TrackingStatus;
  carrier: string;
  eta: string;
  updatedAt: string;
}

export async function fetchTracking(orderId: string): Promise<TrackingUpdate> {
  const response = await fetch(`${API_BASE_URL}/orders/${orderId}/tracking`);
  if (!response.ok) throw new Error(`Tracking failed with status ${response.status}`);
  return (await response.json()) as TrackingUpdate;
}

import { useCallback, useEffect, useState } from 'react';
import { View, Text, StyleSheet, SafeAreaView, ActivityIndicator } from 'react-native';
import { fetchTracking, type TrackingStatus, type TrackingUpdate } from '../services/tracking';

const colors = {
  accent: '#f05039',
  bg: '#0f120e',
  danger: '#ff6b5e',
  text: '#f5f5f0',
  borderAlt: '#2a2f2a',
  muted: '#8a8f8a',
}

const ORDER_ID = 'order-1044';
const STEPS: TrackingStatus[] = ['placed', 'shipped', 'out-for-delivery', 'delivered'];
const POLL_MS = 15_000;

const STEP_LABEL: Record<TrackingStatus, string> = {
  placed: 'Order placed',
  shipped: 'Shipped',
  'out-for-delivery': 'Out for delivery',
  delivered: 'Delivered',
};

export function TrackingScreen(): JSX.Element {
  const [tracking, setTracking] = useState<TrackingUpdate | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    try {
      const data = await fetchTracking(ORDER_ID);
      setTracking(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load tracking.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void load();
    const id = setInterval(() => { void load(); }, POLL_MS);
    return () => clearInterval(id);
  }, [load]);

  const currentIndex = tracking ? STEPS.indexOf(tracking.status) : -1;

  return (
    <SafeAreaView style={styles.safe}>
      {loading && <ActivityIndicator color="{colors.accent}" style={styles.center} />}
      {!loading && error && <Text style={styles.error}>{error}</Text>}
      {!loading && tracking && (
        <View style={styles.content}>
          <Text style={styles.title}>Order {tracking.orderId}</Text>
          <View style={styles.timeline}>
            {STEPS.map((step, index) => {
              const reached = index <= currentIndex;
              const isCurrent = index === currentIndex;
              return (
                <View key={step} style={styles.step} accessibilityLabel={STEP_LABEL[step]}>
                  <View style={[styles.dot, reached && styles.dotReached]}>
                    {isCurrent && <View style={styles.dotPulse} />}
                  </View>
                  <Text style={[styles.stepText, reached && styles.stepTextReached]}>{STEP_LABEL[step]}</Text>
                  {index < STEPS.length - 1 && <View style={[styles.line, reached && styles.lineReached]} />}
                </View>
              );
            })}
          </View>
          <Text style={styles.meta}>
            {tracking.carrier} · ETA {tracking.eta} · updated {new Date(tracking.updatedAt).toLocaleTimeString()}
          </Text>
        </View>
      )}
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1, backgroundColor: colors.bg },
  center: { marginTop: 40 },
  error: { color: colors.danger, textAlign: 'center', marginTop: 24 },
  content: { padding: 20 },
  title: { fontSize: 22, fontWeight: '700', color: colors.text, marginBottom: 24 },
  timeline: { gap: 0 },
  step: { flexDirection: 'row', alignItems: 'flex-start', gap: 12, paddingBottom: 24, position: 'relative' },
  dot: { width: 16, height: 16, borderRadius: 8, backgroundColor: colors.borderAlt, alignItems: 'center', justifyContent: 'center' },
  dotReached: { backgroundColor: colors.accent },
  dotPulse: { width: 6, height: 6, borderRadius: 3, backgroundColor: colors.bg },
  stepText: { color: colors.muted, marginTop: -2 },
  stepTextReached: { color: colors.text, fontWeight: '600' },
  line: { position: 'absolute', left: 7, top: 16, bottom: 0, width: 2, backgroundColor: colors.borderAlt },
  lineReached: { backgroundColor: colors.accent },
  meta: { color: colors.muted, fontSize: 12 },
});
